import { tv, type VariantProps } from "@/lib/beton/tv";

export const alert = tv({
  slots: {
    root: "flex w-full items-start gap-3 border-3 border-border shadow-sm",
    icon: "shrink-0",
    content: "flex min-w-0 flex-1 flex-col gap-1",
    title: "font-display font-extrabold tracking-wide uppercase text-foreground",
    description: "text-foreground",
    actions: "flex flex-wrap items-center gap-3 pt-1",
    close: "-mt-1 -mr-1 shrink-0",
  },
  variants: {
    variant: {
      info: { root: "bg-raised" },
      success: { root: "bg-success/20" },
      warning: { root: "bg-secondary/40" },
      danger: { root: "bg-danger/15" },
    },
    size: {
      sm: { root: "p-3", title: "text-sm", description: "text-sm", icon: "size-5" },
      md: { root: "p-4", title: "text-base", description: "text-base", icon: "size-6" },
      lg: { root: "p-5", title: "text-lg", description: "text-lg", icon: "size-7" },
    },
  },
  defaultVariants: {
    variant: "info",
    size: "md",
  },
});

export type AlertVariants = VariantProps<typeof alert>;

import { alert, type AlertVariants } from "@/lib/beton/recipes/alert.recipe";
import type { ComponentProps, ReactNode } from "react";

export interface AlertProps extends Omit<ComponentProps<"div">, "title">, AlertVariants {
  /** The headline of the message. */
  title?: ReactNode;
  /** A mark before the text. Decorative: it is hidden from screen readers. */
  icon?: ReactNode;
  /** Buttons under the text. */
  actions?: ReactNode;
  /** A dismiss button at the end of the banner. */
  onClose?: ReactNode;
  /**
   * Announces the message as it appears. Use "assertive" only for something
   * that has gone wrong right now.
   */
  live?: "off" | "polite" | "assertive";
}

/** A message that stays on the page: a warning, a result, a piece of context. */
export function Alert({
  variant = "info",
  size = "md",
  title,
  icon,
  actions,
  onClose,
  live,
  className,
  children,
  ...props
}: AlertProps) {
  const styles = alert({ variant, size });
  const assertive = live === "assertive" || (live === undefined && variant === "danger");
  return (
    <div
      {...props}
      role={assertive ? "alert" : "status"}
      aria-live={live === "off" ? "off" : assertive ? "assertive" : "polite"}
      data-variant={variant}
      className={styles.root({ class: className })}
    >
      {icon ? (
        <span aria-hidden="true" className={styles.icon()}>
          {icon}
        </span>
      ) : null}
      <div className={styles.content()}>
        {title ? <p className={styles.title()}>{title}</p> : null}
        {children ? <div className={styles.description()}>{children}</div> : null}
        {actions ? <div className={styles.actions()}>{actions}</div> : null}
      </div>
      {onClose ? <div className={styles.close()}>{onClose}</div> : null}
    </div>
  );
}
